	return vec4f(select(
		o.norface,
		o.nor,
		o.warna_i == 5u,
	),1.,);


	return fsinar(
		vec3f(.5,.6,.5,),
		vec4f(o.norface,1.,),
	) -vec4f(.0,.0,.0,.5,); //vec4f(o.nor,1.,); //vec4f(.5,1.,.5,1.,);
